/* This file declares the interface to the UDP tunnel that carries all Homa
 * packets. Every Homa packet is an ordinary UDP datagram (source and
 * destination port HOMA_UDP_PORT) whose payload is a Homa packet; the
 * IPv4/IPv6 and UDP headers are generated by the kernel's UDP tunnel
 * helpers.
 *
 * Each network namespace owns one inseparable pair of kernel UDP sockets
 * (one IPv4, one IPv6-only), stored in struct homa_net and shared by all
 * Homa application sockets of that namespace. They are created when the
 * namespace is set up and released, after all Homa sockets of the
 * namespace are gone, when it is destroyed. This file declares the
 * functions that manage the pair and the callbacks that the UDP stack
 * invokes on it; transmission goes through homa_route_xmit (homa_peer.h).
 */

#ifndef _HOMA_UDP_TUNNEL_H
#define _HOMA_UDP_TUNNEL_H

#include <linux/types.h>

struct homa_net;
struct net;
struct sk_buff;
struct sock;

int  homa_udp_init(struct homa_net *hnet, struct net *net);
void homa_udp_destroy(struct homa_net *hnet);
int  homa_udp_encap_rcv(struct sock *sk, struct sk_buff *skb);
void homa_udp_encap_err_rcv(struct sock *sk, struct sk_buff *skb, int err,
			    __be16 port, u32 info, u8 *payload);

#endif /* _HOMA_UDP_TUNNEL_H */
